function money(value: number) { return `$${value.toLocaleString("es-CO")}`; }
function initials(name: string) { return name.split(" ").map(p => p[0]).slice(0, 2).join(""); }
function normalizePhone(value: string) { const digits = value.replace(/\D/g, ""); return digits.length === 12 && digits.startsWith("57") ? digits.slice(2) : digits; }
function sanitizeLocalPhone(value: string) { return value.replace(/\D/g, "").slice(0, 10); }
function normalizeEmail(value: string) { return value.trim().toLowerCase(); }

export default function Home() {
  const authMe = trpc.auth.me.useQuery(undefined, { retry: false, refetchOnWindowFocus: false });
  const localLogin = trpc.auth.localLogin.useMutation();
  const serverLogout = trpc.auth.logout.useMutation();
  const [authenticated, setAuthenticated] = useState(() => window.localStorage.getItem("lavanderia_admin_session") === "active");
  const [publicMode, setPublicMode] = useState(() => window.localStorage.getItem("lavanderia_admin_session") !== "active");
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [module, setModule] = useState<Module>(() => new URLSearchParams(window.location.search).get("module") === "configuracion" ? "configuracion" : "dashboard");
  const [tickets, setTickets] = useState(initialTickets);
  const [archivedTickets, setArchivedTickets] = useState<typeof initialTickets>([]);
  const [clients, setClients] = useState(initialClients);
  const [services, setServices] = useState(initialServices);
  const [couriers, setCouriers] = useState(initialCouriers);
  const [selectedTicket, setSelectedTicket] = useState(initialTickets[0]);
  const [previewTicket, setPreviewTicket] = useState<(typeof initialTickets[0] & { archived?: boolean }) | null>(null);
  const [query, setQuery] = useState("");
  const [mobileOpen, setMobileOpen] = useState(false);
  const ticketsQuery = trpc.tickets.list.useQuery(undefined, { retry: false });
  const archivedTicketsQuery = trpc.tickets.archived.useQuery(undefined, { retry: false });
  const clientsQuery = trpc.clients.list.useQuery(undefined, { retry: false });
  const archiveTicket = trpc.tickets.archive.useMutation({ onSuccess: async () => { await Promise.all([ticketsQuery.refetch(), archivedTicketsQuery.refetch()]); toast.success("Ticket archivado; el historial se conserva en Tickets archivados."); }, onError: () => toast.error("No fue posible archivar el ticket") });
  const updateArchivedTicket = trpc.tickets.updateArchived.useMutation({ onSuccess: async (result) => { await Promise.all([ticketsQuery.refetch(), archivedTicketsQuery.refetch()]); if (result.reactivated) { setModule("tickets"); toast.success("Ticket reactivado y devuelto a Domicilios / Tickets"); } else { toast.success("Ticket archivado actualizado"); } }, onError: () => toast.error("No fue posible actualizar el ticket archivado") });
  const deleteArchivedTicket = trpc.tickets.deleteArchived.useMutation({ onSuccess: async () => { await archivedTicketsQuery.refetch(); toast.success("Ticket archivado eliminado definitivamente"); }, onError: () => toast.error("Solo se pueden eliminar tickets archivados") });
  const createPublicTicket = trpc.tickets.createPublic.useMutation();

  useEffect(() => {
    if (ticketsQuery.data) setTickets(ticketsQuery.data as typeof initialTickets);
  }, [ticketsQuery.data]);
  useEffect(() => {
    if (archivedTicketsQuery.data) setArchivedTickets(archivedTicketsQuery.data as typeof initialTickets);
  }, [archivedTicketsQuery.data]);
  useEffect(() => {
    if (clientsQuery.data) setClients(clientsQuery.data as typeof initialClients);
  }, [clientsQuery.data]);

  const counts = useMemo(() => tickets.reduce((acc, t) => ({ ...acc, [t.status]: (acc[t.status] || 0) + 1 }), {} as Record<string, number>), [tickets]);
  useEffect(() => {
    if (authMe.data) {
      window.localStorage.setItem("lavanderia_admin_session", "active");
      setAuthenticated(true);
      setPublicMode(false);
    } else if (!authMe.isLoading && window.localStorage.getItem("lavanderia_admin_session") === "active") {
      window.localStorage.removeItem("lavanderia_admin_session");
      setAuthenticated(false);
      setPublicMode(true);
    }
  }, [authMe.data, authMe.isLoading]);

  const navItems: { key: Module; label: string; icon: typeof LayoutDashboard }[] = [
    { key: "dashboard", label: "Dashboard", icon: LayoutDashboard },
    { key: "clientes", label: "Clientes", icon: Users },
    { key: "servicios", label: "Servicios", icon: Shirt },
    { key: "domiciliarios", label: "Domiciliarios", icon: Truck },
    { key: "tickets", label: "Domicilios / Tickets", icon: ClipboardList },
    { key: "ticketsArchivados", label: "Tickets archivados", icon: Archive },
    { key: "usuarios", label: "Usuarios", icon: UserCog },
    { key: "solicitud", label: "Solicitud pública", icon: Phone },
  ];

  if (!authenticated && publicMode) return <PublicLanding tickets={tickets} setTickets={setTickets} clients={clients} setClients={setClients} services={services} onAdmin={() => setPublicMode(false)} createPublicTicket={createPublicTicket} />;
  if (!authenticated) return <Login username={username} setUsername={setUsername} password={password} setPassword={setPassword} onHome={() => setPublicMode(true)} onLogin={() => localLogin.mutate({ username, password }, { onSuccess: async () => { window.localStorage.setItem("lavanderia_admin_session", "active"); await authMe.refetch(); setAuthenticated(true); setPublicMode(false); setPassword(""); }, onError: () => toast.error("Usuario o contraseña incorrectos.") })} />;

  const activeLabel = navItems.find(item => item.key === module)?.label || "Dashboard";
  const filteredClients = clients.filter(c => `${c.name} ${c.phone}`.toLowerCase().includes(query.toLowerCase()));

  function chooseModule(next: Module) { setModule(next); setMobileOpen(false); }

  return <div className="app-shell">
    <aside className={`sidebar ${mobileOpen ? "sidebar-open" : ""}`}>
      <div className="brand"><div className="brand-mark"><Shirt size={22} /></div><div><strong>Lavanderia</strong><span>Innovation</span></div></div>
      <div className="workspace-label">OPERACIÓN</div>
      <nav className="nav-list">{navItems.map(({ key, label, icon: Icon }) => <button key={key} onClick={() => chooseModule(key)} className={`nav-item ${module === key ? "active" : ""}`}><Icon size={18} /><span>{label}</span>{key === "tickets" && <em>{tickets.length}</em>}</button>)}</nav>
      <div className="sidebar-bottom"><div className="support-card"><Zap size={16} /><div><b>Todo bajo control</b><small>Operación al día</small></div></div><button className={`nav-item ${module === "configuracion" ? "active" : ""}`} onClick={() => chooseModule("configuracion")}><Settings size={18} /><span>Configuración</span></button><button className="profile-mini" onClick={() => { serverLogout.mutate(); window.localStorage.removeItem("lavanderia_admin_session"); setAuthenticated(false); setPublicMode(true); setPassword(""); }}><div className="avatar">AD</div><div><b>Administrador</b><small>Cerrar sesión</small></div><LogOut size={16} /></button></div>
    </aside>
    <main className="main-area">
      <header className="topbar"><button className="mobile-menu" onClick={() => setMobileOpen(!mobileOpen)}><Menu size={20} /></button><div><p className="eyebrow">OPERACIÓN / {activeLabel.toUpperCase()}</p><h1>{activeLabel}</h1></div><div className="top-actions"><div className="search-global"><Search size={17} /><input placeholder="Buscar..." value={query} onChange={e => setQuery(e.target.value)} /></div><button className="icon-button"><Bell size={18} /><i /></button><div className="top-profile"><div className="avatar small">AD</div><span>Administrador</span><ChevronDown size={15} /></div></div></header>
      <div className="page-content">{module === "dashboard" && <Dashboard counts={counts} tickets={tickets} onNavigate={chooseModule} />}{module === "clientes" && <Clients clients={filteredClients} setClients={setClients} />}{module === "servicios" && <Services services={services} setServices={setServices} />}{module === "domiciliarios" && <Couriers couriers={couriers} setCouriers={setCouriers} />}{module === "tickets" && <Tickets tickets={tickets} setTickets={setTickets} clients={clients} setClients={setClients} services={services} couriers={couriers} onArchive={id => archiveTicket.mutate({ id })} onSelect={t => { setSelectedTicket(t); setModule("tickets"); }} onPrint={t => setPreviewTicket(t)} />}{module === "ticketsArchivados" && <ArchivedTickets tickets={archivedTickets} onPrint={t => setPreviewTicket({ ...t, archived: true })} onSave={(ticket) => updateArchivedTicket.mutate({ id: ticket.id, status: ticket.status, totalAmount: ticket.total, notes: ticket.notes })} onDelete={(id) => deleteArchivedTicket.mutate({ id })} />}{module === "usuarios" && <UsersModule />}{module === "factura" && <Invoice ticket={selectedTicket} />}{module === "solicitud" && <PublicRequest />}{module === "configuracion" && <SettingsModule />}</div>
    </main>
    <Dialog open={previewTicket !== null} onOpenChange={open => !open && setPreviewTicket(null)}><DialogContent className="receipt-dialog"><DialogHeader className="receipt-dialog-header"><div><DialogTitle>Factura</DialogTitle><DialogDescription>Vista previa de la tira térmica antes de imprimir.</DialogDescription></div><Button onClick={() => window.print()}><Printer size={16} /> Imprimir</Button></DialogHeader>{previewTicket && <div className="receipt-dialog-scroll"><div className="thermal-receipt">{previewTicket.archived && <div className={`receipt-watermark ${previewTicket.status === "Cancelado" ? "cancelled" : "archived"}`}>{previewTicket.status === "Cancelado" ? "CANCELADO" : "ARCHIVADO"}</div>}<div className="receipt-brand">LAVANDERIA<br />INNOVATION</div><div className="receipt-subtitle">LAVANDERÍA Y TINTORERÍA<br />Zipaquirá, Colombia<br />Tel. +57 300 000 0000</div><div className="receipt-line">================================</div><div className="receipt-meta"><span>TICKET: {previewTicket.ticket}</span><span>{new Date().toLocaleDateString("es-CO")}</span><span>{new Date().toLocaleTimeString("es-CO", { hour: "2-digit", minute: "2-digit" })}</span></div><div className="receipt-line">--------------------------------</div><div className="receipt-section"><b>CLIENTE</b><span>{previewTicket.client}</span><span>Tel. +57 310 482 1930</span><span>Dirección registrada</span></div><div className="receipt-line">--------------------------------</div><div className="receipt-section"><b>SERVICIO</b><span>{previewTicket.service}</span><span>{previewTicket.clothes}</span><span>Estado: {previewTicket.status}</span></div><div className="receipt-line">--------------------------------</div><div className="receipt-total"><span>TOTAL</span><strong>{money(previewTicket.total)}</strong></div><div className="receipt-line">================================</div><div className="receipt-thanks">Gracias por confiar en<br />Lavanderia Innovation</div></div></div>}<DialogFooter><Button variant="outline" onClick={() => setPreviewTicket(null)}>Cerrar</Button><Button className="print-full" onClick={() => window.print()}><Printer size={16} /> Imprimir factura</Button></DialogFooter></DialogContent></Dialog>
  </div>;
}

function Login({ username, setUsername, password, setPassword, onHome, onLogin }: { username: string; setUsername: (v: string) => void; password: string; setPassword: (v: string) => void; onHome: () => void; onLogin: () => void }) { return <div className="login-page"><div className="login-art"><div className="art-orbit orbit-one" /><div className="art-orbit orbit-two" /><div className="login-art-copy"><button className="login-brand brand brand-light" onClick={onHome} aria-label="Volver a la página principal"><div className="brand-mark"><Shirt size={22} /></div><div><strong>Lavanderia</strong><span>Innovation</span></div></button><h1>Ordena tu operación.<br /><em>Eleva tu servicio.</em></h1><p>Una forma más inteligente de gestionar cada prenda, cada domicilio y cada cliente.</p></div><div className="login-art-footer">GESTIÓN INTERNA · ZIPAQUIRÁ, COLOMBIA</div></div><div className="login-panel"><div className="login-box"><div className="login-symbol"><ShieldCheck size={25} /></div><p className="eyebrow">ACCESO SEGURO</p><h2>Bienvenido de nuevo</h2><p className="muted">Ingresa a tu espacio de trabajo en Lavanderia Innovation.</p><label>Usuario</label><Input value={username} onChange={e => setUsername(e.target.value)} placeholder="Escribe tu usuario" autoComplete="username" /><label>Contraseña</label><Input type="password" value={password} onChange={e => setPassword(e.target.value)} onKeyDown={e => e.key === "Enter" && onLogin()} placeholder="Ingresa tu contraseña" /><Button className="login-button" onClick={onLogin}>Acceder <ChevronDown size={17} className="rotate-neg90" /></Button></div><span className="login-copyright">© 2026 Lavanderia Innovation</span></div></div>; }

function PageHeading({ title, description, action }: { title: string; description: string; action?: React.ReactNode }) { return <div className="page-heading"><div><p className="eyebrow">GESTIÓN</p><h2>{title}</h2><p className="muted">{description}</p></div>{action}</div>; }

function Dashboard({ counts, tickets, onNavigate }: { counts: Record<string, number>; tickets: typeof initialTickets; onNavigate: (m: Module) => void }) { return <><div className="welcome-row"><div><p className="eyebrow">MARTES, 18 DE AGOSTO DE 2026</p><h2>Buenos días, Administrador <span>✦</span></h2><p className="muted">Este es el resumen de tu operación para hoy.</p></div><Button onClick={() => onNavigate("tickets")}><Plus size={17} /> Nuevo domicilio</Button></div><div className="metric-grid">{[{ label: "Pendientes", value: counts.Pendiente || 0, accent: "amber", icon: ClipboardList }, { label: "En proceso", value: counts.EnProceso || 0, accent: "blue", icon: Shirt }, { label: "Enrutados", value: counts.Enrutado || 0, accent: "violet", icon: Truck }, { label: "Entregados hoy", value: counts.Entregado || 0, accent: "green", icon: Check }].map(({ label, value, accent, icon: Icon }) => <div className="metric-card" key={label}><div className={`metric-icon ${accent}`}><Icon size={18} /></div><div><p>{label}</p><strong>{value.toString().padStart(2, "0")}</strong></div><span className="metric-trend">+12%</span></div>)}</div><div className="dashboard-grid"><section className="panel quick-panel"><div className="panel-heading"><div><h3>Accesos rápidos</h3><p className="muted">Lo que necesitas, a un clic.</p></div><BarChart3 size={18} className="muted-icon" /></div><div className="quick-grid">{[{ label: "Clientes", icon: Users, module: "clientes" as Module, color: "blue" }, { label: "Servicios", icon: Shirt, module: "servicios" as Module, color: "peach" }, { label: "Domiciliarios", icon: Truck, module: "domiciliarios" as Module, color: "mint" }, { label: "Facturación", icon: FileText, module: "factura" as Module, color: "lavender" }].map(({ label, icon: Icon, module, color }) => <button className="quick-item" onClick={() => onNavigate(module)} key={label}><div className={`quick-icon ${color}`}><Icon size={19} /></div><span>{label}</span><ChevronDown size={14} className="quick-arrow" /></button>)}</div></section><section className="panel status-panel"><div className="panel-heading"><div><h3>Estado de domicilios</h3><p className="muted">Distribución de tickets activos.</p></div></div><div className="status-bars">{(["Pendiente", "EnProceso", "Enrutado", "Entregado"] as Status[]).map(s => <div className="status-bar-row" key={s}><div><span className={`dot ${statusStyles[s]}`} /><span>{s}</span><b>{counts[s] || 0}</b></div><div className="bar"><span className={statusStyles[s]} style={{ width: `${Math.max(8, ((counts[s] || 0) / Math.max(1, tickets.length)) * 100)}%` }} /></div></div>)}</div></section></div><section className="panel recent-panel"><div className="panel-heading"><div><h3>Actividad reciente</h3><p className="muted">Últimos domicilios registrados.</p></div><Button variant="ghost" onClick={() => onNavigate("tickets")}>Ver todos <ChevronDown size={15} className="rotate-neg90" /></Button></div><TicketTable tickets={tickets.slice(0, 3)} compact /></section></>; }

function Clients({ clients, setClients }: { clients: typeof initialClients; setClients: React.Dispatch<React.SetStateAction<typeof initialClients>> }) {
  const [open, setOpen] = useState(false); const [editing, setEditing] = useState<typeof initialClients[0] | null>(null);
  const [form, setForm] = useState({ firstName: "", lastName: "", phone: "", address: "", email: "" });
  const start = (client?: typeof initialClients[0]) => { setEditing(client || null); const parts = (client?.name || "").split(" "); setForm({ firstName: parts[0] || "", lastName: parts.slice(1).join(" "), phone: client?.phone || "", address: client?.address || "", email: client?.email || "" }); setOpen(true); };
  const save = () => { if (!form.firstName || !form.lastName || !form.phone || !form.address || !form.email) { toast.error("Completa todos los campos del cliente"); return; } const phone = normalizePhone(form.phone); if (!/^\d{10}$/.test(phone)) { toast.error("El teléfono debe tener exactamente 10 dígitos numéricos, sin indicativo."); return; } const email = normalizeEmail(form.email); const duplicate = clients.find(item => item.id !== editing?.id && (normalizePhone(item.phone) === phone || (item.email && normalizeEmail(item.email) === email))); if (duplicate) { toast.error(`Ya existe un cliente con ese teléfono o correo: ${duplicate.name}`); return; } const record = { id: editing?.id || Date.now(), name: `${form.firstName} ${form.lastName}`, phone, email, address: form.address }; setClients(prev => editing ? prev.map(item => item.id === editing.id ? record : item) : [...prev, record]); setOpen(false); toast.success(editing ? "Cliente actualizado" : "Cliente creado"); };
  return <><PageHeading title="Clientes" description="Administra la información de tus clientes y sus direcciones." action={<Button onClick={() => start()}><Plus size={17} /> Nuevo Cliente</Button>} /><div className="panel table-panel"><div className="table-toolbar"><div className="table-count">{clients.length} clientes registrados</div><Button variant="outline"><Search size={16} /> Filtrar</Button></div><table><thead><tr><th>CLIENTE</th><th>CONTACTO</th><th>DIRECCIÓN</th><th>ACCIONES</th></tr></thead><tbody>{clients.map(c => <tr key={c.id}><td><div className="person-cell"><div className="avatar table-avatar">{initials(c.name)}</div><div><b>{c.name}</b><small>Cliente #{String(c.id).padStart(3, "0")}</small></div></div></td><td><span>{c.phone}</span><small>{c.email || "Correo no registrado"}</small></td><td>{c.address}<small>Zipaquirá, Colombia</small></td><td><div className="row-actions"><button onClick={() => toast.info(`${c.name} · ${c.phone} · ${c.address}`)}><Eye size={16} /></button><button onClick={() => start(c)}><Pencil size={16} /></button><span className="active-label">Protegido</span></div></td></tr>)}</tbody></table></div><Dialog open={open} onOpenChange={setOpen}><DialogContent className="form-dialog"><DialogHeader><DialogTitle>{editing ? "Editar cliente" : "Nuevo cliente"}</DialogTitle><DialogDescription>Registra los datos de contacto y ubicación del cliente.</DialogDescription></DialogHeader><div className="form-grid"><label>Nombres<Input value={form.firstName} onChange={e => setForm({ ...form, firstName: e.target.value })} placeholder="Nombres" /></label><label>Apellidos<Input value={form.lastName} onChange={e => setForm({ ...form, lastName: e.target.value })} placeholder="Apellidos" /></label><label>Teléfono<Input type="tel" inputMode="numeric" maxLength={10} value={form.phone} onChange={e => setForm({ ...form, phone: sanitizeLocalPhone(e.target.value) })} placeholder="3000000000" /></label><label>Correo electrónico<Input type="email" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} placeholder="cliente@correo.com" /></label><label className="field-full">Dirección<Input value={form.address} onChange={e => setForm({ ...form, address: e.target.value })} placeholder="Calle, carrera, número y barrio" /></label></div><DialogFooter><Button variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button onClick={save}>{editing ? "Guardar cambios" : "Crear cliente"}</Button></DialogFooter></DialogContent></Dialog></>; }

function Services({ services, setServices }: { services: typeof initialServices; setServices: React.Dispatch<React.SetStateAction<typeof initialServices>> }) { const [open, setOpen] = useState(false); const [editing, setEditing] = useState<typeof initialServices[0] | null>(null); const [category, setCategory] = useState<ServiceCategory | "Todos">("Todos"); const [form, setForm] = useState({ name: "", description: "", price: "" }); const start = (s?: typeof initialServices[0]) => { setEditing(s || null); setForm({ name: s?.name || "", description: s?.description || "", price: s ? String(s.price) : "" }); setOpen(true); }; const save = () => { if (!form.name || !form.description || !form.price) return toast.error("Completa todos los campos del servicio"); const record = { id: editing?.id || Date.now(), name: form.name, description: form.description, price: Number(form.price), category: editing?.category || "Ropa de hombre", active: editing?.active ?? true }; setServices(prev => editing ? prev.map(item => item.id === editing.id ? record : item) : [...prev, record]); setOpen(false); toast.success(editing ? "Servicio actualizado" : "Servicio creado"); }; const visibleServices = category === "Todos" ? services : services.filter(service => service.category === category); return <><PageHeading title="Servicios" description="Configura el catálogo que ofrece Lavanderia Innovation." action={<Button onClick={() => start()}><Plus size={17} /> Nuevo Servicio</Button>} /><div className="segment-tabs">{["Todos", ...serviceCategories].map(item => <button key={item} className={category === item ? "active" : ""} onClick={() => setCategory(item as ServiceCategory | "Todos")}>{item}</button>)}</div><div className="service-grid">{visibleServices.map(s => <div className={`service-card ${!s.active ? "inactive" : ""}`} key={s.id}><div className="service-top"><div className="service-icon"><Shirt size={20} /></div><div className="service-actions"><button onClick={() => start(s)}><Pencil size={14} /></button><button onClick={() => { if (window.confirm(`¿Eliminar ${s.name}?`)) setServices(prev => prev.filter(item => item.id !== s.id)); }}><Trash2 size={14} /></button><Switch checked={s.active} onCheckedChange={checked => setServices(prev => prev.map(item => item.id === s.id ? { ...item, active: checked } : item))} /></div></div><span className="service-category">{s.category}</span><h3>{s.name}</h3><p>{s.description}</p><div className="service-bottom"><strong>{money(s.price)}</strong><span className={s.active ? "active-label" : "inactive-label"}>{s.active ? "Activo" : "Inactivo"}</span></div></div>)}</div><Dialog open={open} onOpenChange={setOpen}><DialogContent className="form-dialog"><DialogHeader><DialogTitle>{editing ? "Editar servicio" : "Nuevo servicio"}</DialogTitle><DialogDescription>Configura el servicio y su precio.</DialogDescription></DialogHeader><div className="form-grid"><label className="field-full">Nombre<Input value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} /></label><label className="field-full">Descripción<Input value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} /></label><label>Precio<Input type="number" value={form.price} onChange={e => setForm({ ...form, price: e.target.value })} /></label></div><DialogFooter><Button variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button onClick={save}>Guardar servicio</Button></DialogFooter></DialogContent></Dialog></>; }

function Couriers({ couriers, setCouriers }: { couriers: typeof initialCouriers; setCouriers: React.Dispatch<React.SetStateAction<typeof initialCouriers>> }) { const [open, setOpen] = useState(false); const [editing, setEditing] = useState<typeof initialCouriers[0] | null>(null); const [form, setForm] = useState({ name: "", phone: "" }); const start = (c?: typeof initialCouriers[0]) => { setEditing(c || null); setForm({ name: c?.name || "", phone: c?.phone || "" }); setOpen(true); }; const save = () => { if (!form.name || !form.phone) return toast.error("Completa nombre y teléfono"); const record = { id: editing?.id || Date.now(), name: form.name, phone: form.phone, active: editing?.active ?? true }; setCouriers(prev => editing ? prev.map(item => item.id === editing.id ? record : item) : [...prev, record]); setOpen(false); toast.success(editing ? "Domiciliario actualizado" : "Domiciliario creado"); }; return <><PageHeading title="Domiciliarios" description="Gestiona tu equipo de entrega y su disponibilidad." action={<Button onClick={() => start()}><Plus size={17} /> Nuevo domiciliario</Button>} /><div className="courier-grid">{couriers.map(c => <div className="courier-card" key={c.id}><div className="person-cell"><div className="avatar table-avatar courier-avatar">{initials(c.name)}</div><div><b>{c.name}</b><small><Phone size={12} /> {c.phone}</small></div><div className="row-actions"><button onClick={() => start(c)}><Pencil size={14} /></button><button onClick={() => { if (window.confirm(`¿Eliminar ${c.name}?`)) setCouriers(prev => prev.filter(item => item.id !== c.id)); }}><Trash2 size={14} /></button></div></div><div className="courier-footer"><span className={c.active ? "active-label" : "inactive-label"}>{c.active ? "Disponible" : "No disponible"}</span><Switch checked={c.active} onCheckedChange={checked => setCouriers(prev => prev.map(item => item.id === c.id ? { ...item, active: checked } : item))} /></div></div>)}</div><Dialog open={open} onOpenChange={setOpen}><DialogContent className="form-dialog"><DialogHeader><DialogTitle>{editing ? "Editar domiciliario" : "Nuevo domiciliario"}</DialogTitle></DialogHeader><div className="form-grid"><label className="field-full">Nombre completo<Input value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} /></label><label className="field-full">Teléfono<Input value={form.phone} onChange={e => setForm({ ...form, phone: e.target.value })} /></label></div><DialogFooter><Button variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button onClick={save}>Guardar domiciliario</Button></DialogFooter></DialogContent></Dialog></>; }

function Tickets({ tickets, setTickets, clients, setClients, services, couriers, onArchive, onSelect, onPrint }: { tickets: typeof initialTickets; setTickets: React.Dispatch<React.SetStateAction<typeof initialTickets>>; clients: typeof initialClients; setClients: React.Dispatch<React.SetStateAction<typeof initialClients>>; services: typeof initialServices; couriers: typeof initialCouriers; onArchive: (id: number) => void; onSelect: (ticket: typeof initialTickets[0]) => void; onPrint: (ticket: typeof initialTickets[0]) => void }) {
  const [open, setOpen] = useState(false);
  const [quickClientOpen, setQuickClientOpen] = useState(false);
  const [editing, setEditing] = useState<typeof initialTickets[0] | null>(null);
  const [ticketSearch, setTicketSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState<Status | "Todos">("Todos");
  const [clientForm, setClientForm] = useState({ firstName: "", lastName: "", phone: "", address: "", email: "" });
  const [form, setForm] = useState({ client: "", service: "", courier: "", status: "Pendiente" as Status, total: "", day: "Lunes", pickup: "9:30 a. m. - 12:30 p. m.", delivery: "2:30 p. m. - 5:00 p. m.", clothes: "", notes: "" });
  const activeServices = services.filter(service => service.active);
  const start = (t?: typeof initialTickets[0]) => { setEditing(t || null); setForm({ client: t?.client || "", service: t?.service || "", courier: t?.courier || "", status: t?.status || "Pendiente", total: t ? String(t.total) : "", day: "Lunes", pickup: t?.pickup || "9:30 a. m. - 12:30 p. m.", delivery: t?.delivery || "2:30 p. m. - 5:00 p. m.", clothes: t?.clothes || "", notes: t?.notes || "" }); setOpen(true); };
  const chooseService = (value: string) => { const selected = activeServices.find(service => service.name === value); setForm(prev => ({ ...prev, service: value, total: selected ? String(selected.price) : prev.total })); };
  const save = () => { if (!form.client || !form.service || !form.total || !form.clothes) return toast.error("Completa cliente, servicio, valor y descripción de prendas"); const record = { id: editing?.id || Date.now(), ticket: editing?.ticket || "TK-" + String(Math.max(0, ...tickets.map(ticket => ticket.id)) + 1).padStart(6, "0"), client: form.client, service: form.service, courier: form.courier || "Sin asignar", status: form.status, total: Number(form.total), pickup: form.pickup, delivery: form.delivery, clothes: form.clothes, notes: form.notes }; setTickets(prev => editing ? prev.map(item => item.id === editing.id ? record : item) : [record, ...prev]); setOpen(false); toast.success(editing ? "Domicilio actualizado" : "Domicilio creado"); };
  const saveQuickClient = () => { if (!clientForm.firstName || !clientForm.lastName || !clientForm.phone || !clientForm.address || !clientForm.email) return toast.error("Completa todos los campos del cliente"); const phone = normalizePhone(clientForm.phone); if (!/^\d{10}$/.test(phone)) { toast.error("El teléfono debe tener exactamente 10 dígitos numéricos, sin indicativo."); return; } const email = normalizeEmail(clientForm.email); const duplicate = clients.find(item => normalizePhone(item.phone) === phone || (item.email && normalizeEmail(item.email) === email)); if (duplicate) return toast.error(`Ya existe un cliente con ese teléfono o correo: ${duplicate.name}`); const record = { id: Date.now(), name: clientForm.firstName + " " + clientForm.lastName, phone, email, address: clientForm.address }; setClients(prev => [...prev, record]); setForm(prev => ({ ...prev, client: record.name })); setClientForm({ firstName: "", lastName: "", phone: "", address: "", email: "" }); setQuickClientOpen(false); toast.success("Cliente creado y seleccionado"); };
  const visibleTickets = tickets.filter(ticket => { const haystack = (ticket.ticket + " " + ticket.client + " " + ticket.service).toLowerCase(); return (!ticketSearch || haystack.includes(ticketSearch.toLowerCase())) && (statusFilter === "Todos" || ticket.status === statusFilter); });
  return <><PageHeading title="Domicilios" description="Gestión de tickets de domicilio y seguimiento operativo." action={<Button onClick={() => start()}><Plus size={17} /> Nuevo Domicilio</Button>} /><div className="panel table-panel ticket-panel"><div className="table-toolbar"><div className="table-count"><span className="live-dot" /> {visibleTickets.length} de {tickets.length} tickets</div><div className="toolbar-actions"><label className="ticket-search"><Search size={16} /><input value={ticketSearch} onChange={e => setTicketSearch(e.target.value)} placeholder="Buscar ticket, cliente o servicio" /></label><label className="status-filter"><ClipboardList size={16} /><select value={statusFilter} onChange={e => setStatusFilter(e.target.value as Status | "Todos")}><option value="Todos">Todos los estados</option>{(["Pendiente", "EnProceso", "Enrutado", "Entregado", "Cancelado"] as Status[]).map(status => <option key={status} value={status}>{status}</option>)}</select></label></div></div>{(ticketSearch || statusFilter !== "Todos") && <div className="active-filters"><span>Filtros activos</span>{ticketSearch && <button onClick={() => setTicketSearch("")}>Búsqueda: {ticketSearch} <X size={13} /></button>}{statusFilter !== "Todos" && <button onClick={() => setStatusFilter("Todos")}>Estado: {statusFilter} <X size={13} /></button>}</div>}<TicketTable tickets={visibleTickets} onArchive={onArchive} onSelect={onSelect} onEdit={start} onPrint={onPrint} onStatusChange={(id, status) => setTickets(prev => prev.map(item => item.id === id ? { ...item, status } : item))} /></div><Dialog open={open} onOpenChange={setOpen}><DialogContent className="form-dialog ticket-form-dialog"><DialogHeader><DialogTitle>{editing ? "Editar domicilio" : "Nuevo domicilio"}</DialogTitle><DialogDescription>Registra la información completa del ticket de recogida y entrega.</DialogDescription></DialogHeader><div className="form-grid"><label>Cliente<select value={form.client} onChange={e => { if (e.target.value === "__new__") { setQuickClientOpen(true); return; } setForm({ ...form, client: e.target.value }); }}><option value="">Selecciona un cliente</option>{clients.map(client => <option key={client.id} value={client.name}>{client.name} · {client.phone}</option>)}<option value="__new__">+ Crear cliente nuevo</option></select></label><label>Servicio<select value={form.service} onChange={e => chooseService(e.target.value)}><option value="">Selecciona un servicio</option>{activeServices.map(service => <option key={service.id} value={service.name}>{service.name} · {money(service.price)}</option>)}</select></label><label>Domiciliario<select value={form.courier} onChange={e => setForm({ ...form, courier: e.target.value })}><option value="">Sin asignar</option>{couriers.filter(courier => courier.active || courier.name === form.courier).map(courier => <option key={courier.id} value={courier.name}>{courier.name} · {courier.phone}{!courier.active ? " · No disponible" : ""}</option>)}</select></label><label>Estado<select value={form.status} onChange={e => setForm({ ...form, status: e.target.value as Status })}>{(["Pendiente", "EnProceso", "Enrutado", "Entregado", "Cancelado"] as Status[]).map(s => <option key={s}>{s}</option>)}</select></label><label>Valor total<Input type="number" value={form.total} onChange={e => setForm({ ...form, total: e.target.value })} placeholder="0" /></label><label>Día<select value={form.day} onChange={e => setForm({ ...form, day: e.target.value, pickup: e.target.value === "Sábado" ? "9:30 a. m. - 12:00 p. m." : "9:30 a. m. - 12:30 p. m.", delivery: e.target.value === "Sábado" ? "9:30 a. m. - 12:00 p. m." : "2:30 p. m. - 5:00 p. m." })}><option>Lunes</option><option>Martes</option><option>Miércoles</option><option>Jueves</option><option>Viernes</option><option>Sábado</option></select></label><label>Recogida<select value={form.pickup} onChange={e => setForm({ ...form, pickup: e.target.value })}>{form.day === "Sábado" ? <option>9:30 a. m. - 12:00 p. m.</option> : <><option>9:30 a. m. - 12:30 p. m.</option><option>2:30 p. m. - 5:00 p. m.</option></>}</select></label><label>Entrega<select value={form.delivery} onChange={e => setForm({ ...form, delivery: e.target.value })}>{form.day === "Sábado" ? <option>9:30 a. m. - 12:00 p. m.</option> : <><option>2:30 p. m. - 5:00 p. m.</option><option>9:30 a. m. - 12:30 p. m.</option></>}</select></label><label className="field-full">Descripción de prendas<Input value={form.clothes} onChange={e => setForm({ ...form, clothes: e.target.value })} placeholder="Ej. 2 camisas, 1 pantalón" /></label><label className="field-full">Notas adicionales<Input value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} placeholder="Indicaciones especiales" /></label></div><DialogFooter><Button variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button onClick={save}>Guardar domicilio</Button></DialogFooter></DialogContent></Dialog><Dialog open={quickClientOpen} onOpenChange={setQuickClientOpen}><DialogContent className="form-dialog"><DialogHeader><DialogTitle>Crear cliente</DialogTitle><DialogDescription>Usa el mismo formulario de Clientes para registrar un nuevo contacto.</DialogDescription></DialogHeader><div className="form-grid"><label>Nombres<Input value={clientForm.firstName} onChange={e => setClientForm({ ...clientForm, firstName: e.target.value })} placeholder="Nombres" /></label><label>Apellidos<Input value={clientForm.lastName} onChange={e => setClientForm({ ...clientForm, lastName: e.target.value })} placeholder="Apellidos" /></label><label>Teléfono<Input type="tel" inputMode="numeric" maxLength={10} value={clientForm.phone} onChange={e => setClientForm({ ...clientForm, phone: sanitizeLocalPhone(e.target.value) })} placeholder="3000000000" /></label><label>Correo electrónico<Input type="email" value={clientForm.email} onChange={e => setClientForm({ ...clientForm, email: e.target.value })} placeholder="cliente@correo.com" /></label><label className="field-full">Dirección<Input value={clientForm.address} onChange={e => setClientForm({ ...clientForm, address: e.target.value })} placeholder="Calle, carrera, número y barrio" /></label></div><DialogFooter><Button variant="outline" onClick={() => setQuickClientOpen(false)}>Cancelar</Button><Button onClick={saveQuickClient}>Crear cliente</Button></DialogFooter></DialogContent></Dialog></>;
}
function ArchivedTickets({ tickets, onPrint, onSave, onDelete }: { tickets: typeof initialTickets; onPrint: (ticket: typeof initialTickets[0]) => void; onSave: (ticket: typeof initialTickets[0]) => void; onDelete: (id: number) => void }) {
  const [editing, setEditing] = useState<typeof initialTickets[0] | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<typeof initialTickets[0] | null>(null);
  const [form, setForm] = useState({ status: "Pendiente" as Status, total: "", notes: "" });
  const startEdit = (ticket: typeof initialTickets[0]) => { setEditing(ticket); setForm({ status: ticket.status, total: String(ticket.total), notes: ticket.notes }); };
  const save = () => { if (!editing || !form.total || Number(form.total) < 0) return toast.error("Ingresa un total válido"); onSave({ ...editing, status: form.status, total: Number(form.total), notes: form.notes }); setEditing(null); };
  return <><PageHeading title="Tickets archivados" description="Historial protegido. Puedes editar, reactivar o eliminar definitivamente un ticket archivado." /><div className="panel table-panel ticket-panel"><div className="table-toolbar"><div className="table-count"><Archive size={16} /> {tickets.length} tickets archivados</div></div><TicketTable tickets={tickets} archivedView onPrint={onPrint} onEdit={startEdit} onDelete={setDeleteTarget} /></div><Dialog open={editing !== null} onOpenChange={open => !open && setEditing(null)}><DialogContent className="form-dialog"><DialogHeader><DialogTitle>Editar ticket archivado</DialogTitle><DialogDescription>Al elegir un estado operativo, el ticket volverá automáticamente a Domicilios / Tickets.</DialogDescription></DialogHeader><div className="form-grid"><label>Estado<select value={form.status} onChange={e => setForm({ ...form, status: e.target.value as Status })}>{(["Pendiente", "EnProceso", "Enrutado", "Entregado", "Cancelado"] as Status[]).map(status => <option key={status}>{status}</option>)}</select></label><label>Total<Input type="number" min="0" value={form.total} onChange={e => setForm({ ...form, total: e.target.value })} /></label><label className="field-full">Notas<Input value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} /></label></div><DialogFooter><Button variant="outline" onClick={() => setEditing(null)}>Cancelar</Button><Button onClick={save}>Guardar cambios</Button></DialogFooter></DialogContent></Dialog><Dialog open={deleteTarget !== null} onOpenChange={open => !open && setDeleteTarget(null)}><DialogContent className="delete-dialog"><div className="delete-icon"><Trash2 size={22} /></div><DialogHeader><DialogTitle>¿Eliminar definitivamente este ticket?</DialogTitle><DialogDescription>Esta acción solo está disponible para tickets archivados y no se puede deshacer. Se eliminará <b>{deleteTarget?.ticket}</b> del histórico.</DialogDescription></DialogHeader><DialogFooter><Button variant="outline" onClick={() => setDeleteTarget(null)}>Cancelar</Button><Button className="danger-button" onClick={() => { if (deleteTarget) { onDelete(deleteTarget.id); setDeleteTarget(null); } }}><Trash2 size={16} /> Eliminar definitivamente</Button></DialogFooter></DialogContent></Dialog></>;
}

function TicketTable({ tickets, compact = false, archivedView = false, onArchive, onSelect, onEdit, onPrint, onDelete, onStatusChange }: { tickets: typeof initialTickets; compact?: boolean; archivedView?: boolean; onArchive?: (id: number) => void; onSelect?: (ticket: typeof initialTickets[0]) => void; onEdit?: (ticket: typeof initialTickets[0]) => void; onPrint?: (ticket: typeof initialTickets[0]) => void; onDelete?: (ticket: typeof initialTickets[0]) => void; onStatusChange?: (id: number, status: Status) => void }) { return <div className="table-scroll"><table><thead><tr><th>TICKET</th><th>CLIENTE</th><th>SERVICIO</th>{!compact && <th>PERSONAL</th>}<th>ESTADO</th><th>TOTAL</th>{!compact && <><th>RECOGIDA</th><th>ENTREGA</th></>}<th>ACCIONES</th></tr></thead><tbody>{tickets.map(t => <tr key={t.id}><td><button className="ticket-link" onClick={() => onSelect?.(t)}>{t.ticket}</button></td><td><b>{t.client}</b></td><td>{t.service}</td>{!compact && <td>{t.courier || "—"}</td>}<td>{archivedView ? <span className="status-badge status-archived"><i />Archivado</span> : <select className={`status-select ${statusStyles[t.status]}`} value={t.status} onChange={e => onStatusChange?.(t.id, e.target.value as Status)}>{(["Pendiente", "EnProceso", "Enrutado", "Entregado", "Cancelado"] as Status[]).map(s => <option key={s}>{s}</option>)}</select>}</td><td><b>{money(t.total)}</b></td>{!compact && <><td>{t.pickup}</td><td>{t.delivery}</td></>}<td><div className="row-actions"><button title="Ver detalle" onClick={() => onSelect?.(t)}><Eye size={16} /></button>{onPrint && <button title="Imprimir" onClick={() => onPrint(t)}><Printer size={16} /></button>}{onEdit && <button title="Editar" onClick={() => onEdit(t)}><Pencil size={16} /></button>}{onArchive && <button title="Archivar ticket" onClick={() => onArchive(t.id)}><Archive size={16} /></button>}{onDelete && <button title="Eliminar definitivamente" onClick={() => onDelete(t)}><Trash2 size={16} /></button>}</div></td></tr>)}</tbody></table></div>; }

function UsersModule() {
  const usersQuery = trpc.users.list.useQuery();
  const createUser = trpc.users.create.useMutation({ onSuccess: () => usersQuery.refetch() });
  const updateUser = trpc.users.update.useMutation({ onSuccess: () => usersQuery.refetch() });
  const deleteUserMutation = trpc.users.delete.useMutation({ onSuccess: () => usersQuery.refetch() });
  const users = (usersQuery.data || []).map(user => ({ ...user, name: user.username, active: true }));
  const [open, setOpen] = useState(false);
  const [editing, setEditing] = useState<typeof users[0] | null>(null);
  const [deleteUser, setDeleteUser] = useState<typeof users[0] | null>(null);
  const [form, setForm] = useState({ username: "", name: "", role: "Empleado" as "Administrador" | "Empleado", password: "" });
  const start = (u?: typeof users[0]) => { setEditing(u || null); setForm({ username: u?.username || "", name: u?.name || "", role: u?.role || "Empleado", password: "" }); setOpen(true); };
  const save = () => {
    if (!form.username || !form.name || (!editing && form.password.length < 6)) return toast.error("Completa usuario, nombre y una contraseña de mínimo 6 caracteres");
    const onError = () => toast.error("No fue posible guardar el usuario");
    if (editing) updateUser.mutate({ id: editing.id, username: form.username, role: form.role, ...(form.password ? { password: form.password } : {}) }, { onSuccess: () => { setOpen(false); toast.success("Usuario actualizado"); }, onError });
    else createUser.mutate({ username: form.username, password: form.password, role: form.role }, { onSuccess: () => { setOpen(false); toast.success("Usuario creado"); }, onError });
  };
  return <><PageHeading title="Usuarios" description="Administra accesos y roles del equipo interno." action={<Button onClick={() => start()}><Plus size={17} /> Nuevo usuario</Button>} /><div className="panel user-summary"><div className="user-summary-icon"><ShieldCheck size={22} /></div><div><h3>Autenticación local activa</h3><p className="muted">Los usuarios ingresan con su propio usuario y contraseña.</p></div><span className="active-label">Protegido</span></div><div className="panel table-panel"><table><thead><tr><th>USUARIO</th><th>ROL</th><th>ÚLTIMO ACCESO</th><th>ESTADO</th><th>ACCIONES</th></tr></thead><tbody>{users.map(u => <tr key={u.id}><td><div className="person-cell"><div className="avatar table-avatar">{initials(u.username)}</div><div><b>{u.username}</b><small>{u.name}</small></div></div></td><td><span className={`role-badge ${u.role === "Administrador" ? "admin" : "employee"}`}>{u.role}</span></td><td>Registrado</td><td><span className="active-label">Activo</span></td><td><div className="row-actions"><button onClick={() => start(u)}><Pencil size={16} /></button><button onClick={() => setDeleteUser(u)}><Trash2 size={16} /></button></div></td></tr>)}</tbody></table></div><Dialog open={open} onOpenChange={setOpen}><DialogContent className="form-dialog"><DialogHeader><DialogTitle>{editing ? "Editar usuario" : "Nuevo usuario"}</DialogTitle><DialogDescription>Configura el acceso y rol del usuario.</DialogDescription></DialogHeader><div className="form-grid"><label>Usuario<Input value={form.username} onChange={e => setForm({ ...form, username: e.target.value })} /></label><label>Nombre completo<Input value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} /></label><label>Contraseña<Input type="password" value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} placeholder={editing ? "Dejar en blanco para conservar" : "Mínimo 6 caracteres"} /></label><label>Rol<select value={form.role} onChange={e => setForm({ ...form, role: e.target.value as "Administrador" | "Empleado" })}><option>Empleado</option><option>Administrador</option></select></label></div><DialogFooter><Button variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button onClick={save}>Guardar usuario</Button></DialogFooter></DialogContent></Dialog><Dialog open={deleteUser !== null} onOpenChange={open => !open && setDeleteUser(null)}><DialogContent className="delete-dialog"><div className="delete-icon"><Trash2 size={22} /></div><DialogHeader><DialogTitle>¿Eliminar este usuario?</DialogTitle><DialogDescription>Se revocará el acceso de <b>{deleteUser?.username}</b> al sistema.</DialogDescription></DialogHeader><DialogFooter><Button variant="outline" onClick={() => setDeleteUser(null)}>Cancelar</Button><Button className="danger-button" onClick={() => { if (deleteUser) deleteUserMutation.mutate({ id: deleteUser.id }, { onSuccess: () => { setDeleteUser(null); toast.success("Usuario eliminado"); }, onError: () => toast.error("No fue posible eliminar el usuario") }); }}><Trash2 size={16} /> Eliminar usuario</Button></DialogFooter></DialogContent></Dialog></>;
}

export function SettingsModule() {
  const [business, setBusiness] = useState({ name: "Lavanderia Innovation", city: "Zipaquirá", phone: "+57 322 611 1910", whatsapp: "+573226111910" });
  const [hours, setHours] = useState({ weekday: "9:30 a. m. - 12:30 p. m. / 2:30 p. m. - 5:00 p. m.", saturday: "9:30 a. m. - 12:00 p. m.", sunday: "Sin servicio" });
  const [saved, setSaved] = useState(false);
  const updateBusiness = (key: keyof typeof business, value: string) => setBusiness(current => ({ ...current, [key]: value }));
  const updateHours = (key: keyof typeof hours, value: string) => setHours(current => ({ ...current, [key]: value }));
  function saveSettings() { setSaved(true); toast.success("Configuración guardada en esta sesión"); setTimeout(() => setSaved(false), 2200); }
  return <><PageHeading title="Configuración" description="Administra la información operativa que utiliza Lavanderia Innovation." action={<Button onClick={saveSettings}><Check size={16} /> Guardar cambios</Button>} />
    <div className="settings-grid">
      <section className="panel settings-card"><div className="panel-heading"><div><h3>Información del negocio</h3><p className="muted">Estos datos identifican la operación y el canal de contacto.</p></div><Settings size={20} className="muted-icon" /></div><div className="settings-fields"><label>Nombre del negocio<Input value={business.name} onChange={e => updateBusiness("name", e.target.value)} /></label><label>Ciudad<Input value={business.city} onChange={e => updateBusiness("city", e.target.value)} /></label><label>Teléfono visible<Input value={business.phone} onChange={e => updateBusiness("phone", e.target.value)} /></label><label>Número de WhatsApp<Input value={business.whatsapp} onChange={e => updateBusiness("whatsapp", e.target.value)} /></label></div></section>
      <section className="panel settings-card"><div className="panel-heading"><div><h3>Horarios de recogida</h3><p className="muted">Se muestran en la solicitud pública para orientar al cliente.</p></div><ClipboardList size={20} className="muted-icon" /></div><div className="settings-fields"><label>Lunes a viernes<Input value={hours.weekday} onChange={e => updateHours("weekday", e.target.value)} /></label><label>Sábado<Input value={hours.saturday} onChange={e => updateHours("saturday", e.target.value)} /></label><label>Domingo<Input value={hours.sunday} onChange={e => updateHours("sunday", e.target.value)} /></label></div></section>
    </div>
    {saved && <div className="settings-saved"><Check size={16} /> Cambios guardados correctamente.</div>}
  </>;
}

function PublicRequest() { const [name, setName] = useState(""); const [phone, setPhone] = useState(""); const [address, setAddress] = useState(""); const [slot, setSlot] = useState("10:00 AM - 12:00 PM"); const message = `Hola, soy ${name || "un cliente"}. Quiero solicitar un servicio de lavandería. Teléfono: ${phone}. Dirección: ${address}. Horario: ${slot}.`; return <><PageHeading title="Solicitud pública" description="Recibe solicitudes de recogida y envíalas por WhatsApp al equipo." /><div className="request-layout"><div className="panel request-card"><div className="panel-heading"><div><h3>Solicitar recogida</h3><p className="muted">Completa los datos y continúa la conversación por WhatsApp.</p></div><Phone size={20} className="muted-icon" /></div><div className="request-fields"><label>Nombre completo<Input value={name} onChange={e => setName(e.target.value)} placeholder="Ej. Laura Gómez" /></label><label>Teléfono<Input value={phone} onChange={e => setPhone(e.target.value)} placeholder="3000000000" /></label><label>Dirección de recogida<Input value={address} onChange={e => setAddress(e.target.value)} placeholder="Dirección y barrio" /></label><label>Franja horaria<select value={slot} onChange={e => setSlot(e.target.value)}><option>10:00 AM - 12:00 PM</option><option>1:00 PM - 3:00 PM</option><option>3:00 PM - 5:00 PM</option></select></label></div><a className="whatsapp-button" href={`https://wa.me/573000000000?text=${encodeURIComponent(message)}`} target="_blank" rel="noreferrer"><Phone size={17} /> Enviar solicitud por WhatsApp</a></div><div className="panel request-note"><div className="request-note-icon"><Zap size={20} /></div><h3>Un canal, menos esperas.</h3><p className="muted">La solicitud llegará al número operativo de Lavanderia Innovation con los datos de recogida listos para crear el ticket.</p><div className="request-step"><b>01</b><span>Completa los datos del cliente.</span></div><div className="request-step"><b>02</b><span>Envía el mensaje a WhatsApp.</span></div><div className="request-step"><b>03</b><span>El equipo confirma la recogida.</span></div></div></div></>; }

function Invoice({ ticket }: { ticket: typeof initialTickets[0] }) { return <><div className="invoice-heading no-print"><div><p className="eyebrow">FACTURACIÓN / {ticket.ticket}</p><h2>Factura</h2><p className="muted">Vista previa del recibo térmico.</p></div><Button onClick={() => window.print()}><Printer size={17} /> Imprimir</Button></div><div className="invoice-layout"><div className="invoice-preview"><div className="thermal-receipt"><div className="receipt-brand">LAVANDERIA<br />INNOVATION</div><div className="receipt-subtitle">LAVANDERÍA Y TINTORERÍA<br />Zipaquirá, Colombia<br />Tel. +57 300 000 0000</div><div className="receipt-line">================================</div><div className="receipt-meta"><span>TICKET: {ticket.ticket}</span><span>{new Date().toLocaleDateString("es-CO")}</span><span>{new Date().toLocaleTimeString("es-CO", { hour: "2-digit", minute: "2-digit" })}</span></div><div className="receipt-line">--------------------------------</div><div className="receipt-section"><b>CLIENTE</b><span>{ticket.client}</span><span>Tel. +57 310 482 1930</span><span>Dirección registrada</span></div><div className="receipt-line">--------------------------------</div><div className="receipt-section"><b>SERVICIO</b><span>{ticket.service}</span><span>{ticket.clothes}</span><span>Estado: {ticket.status}</span></div><div className="receipt-line">--------------------------------</div><div className="receipt-total"><span>TOTAL</span><strong>{money(ticket.total)}</strong></div><div className="receipt-line">================================</div><div className="receipt-thanks">Gracias por confiar en<br />Lavanderia Innovation</div></div></div><div className="invoice-side no-print"><div className="panel invoice-info"><div className="panel-heading"><h3>Resumen del ticket</h3><span className={`status-badge ${statusStyles[ticket.status]}`}><i />{ticket.status}</span></div><div className="info-row"><span>Cliente</span><b>{ticket.client}</b></div><div className="info-row"><span>Recogida</span><b>{ticket.pickup}</b></div><div className="info-row"><span>Entrega</span><b>{ticket.delivery}</b></div><div className="info-row"><span>Domiciliario</span><b>{ticket.courier}</b></div><div className="info-row total-row"><span>Total</span><b>{money(ticket.total)}</b></div></div><Button className="print-full" onClick={() => window.print()}><Printer size={17} /> Imprimir factura</Button></div></div></>; }


function PublicLanding({ tickets, setTickets, clients, setClients, services, onAdmin, createPublicTicket }: { tickets: typeof initialTickets; setTickets: React.Dispatch<React.SetStateAction<typeof initialTickets>>; clients: typeof initialClients; setClients: React.Dispatch<React.SetStateAction<typeof initialClients>>; services: typeof initialServices; onAdmin: () => void; createPublicTicket: ReturnType<typeof trpc.tickets.createPublic.useMutation> }) {
  const activeServices = services.filter(service => service.active);
  const [showServices, setShowServices] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<ServiceCategory | "Todos">("Todos");
  const visibleServices = selectedCategory === "Todos" ? activeServices : activeServices.filter(service => service.category === selectedCategory);
  const [form, setForm] = useState(() => ({ name: "", phone: "", email: "", address: "", service: activeServices[0]?.name || "", day: "Lunes", clothes: "", pickup: "9:30 a. m. - 12:30 p. m.", delivery: "2:30 p. m. - 5:00 p. m.", notes: "" }));
  const [sent, setSent] = useState(false);
  const [previewTicket, setPreviewTicket] = useState<(typeof initialTickets[0] & { phone: string; address: string; archived?: boolean }) | null>(null);
  const submit = (event: React.FormEvent) => {
    event.preventDefault();
    if (!form.name || !form.phone || !form.address || !form.service || !form.clothes) return toast.error("Completa nombre, teléfono, dirección, servicio y prendas");
    if (!/^\d{10}$/.test(form.phone)) return toast.error("El teléfono debe tener exactamente 10 dígitos numéricos, sin indicativo.");
    const service = activeServices.find(item => item.name === form.service) || activeServices[0];
    const requestedPrice = service?.price || 0;
    const draftTicket = { id: Date.now(), ticket: `TK-${String(Date.now()).slice(-5)}`, client: form.name, phone: form.phone, address: form.address, service: form.service, courier: "Sin asignar", status: "Pendiente" as Status, total: requestedPrice, pickup: form.pickup, delivery: form.delivery, clothes: form.clothes, notes: form.notes || "Solicitud recibida desde la web" };
    createPublicTicket.mutate({ ...form, servicePrice: requestedPrice }, {
      onSuccess: result => {
        const persistedTicket = { ...draftTicket, id: result.id, ticket: result.ticketNumber, total: result.total };
        const message = `Hola, Lavanderia Innovation. Quiero confirmar mi pedido ${persistedTicket.ticket}. Cliente: ${form.name}. Teléfono: ${form.phone}. Dirección: ${form.address}. Servicio: ${form.service}. Prendas: ${form.clothes}. Día: ${form.day}. Recogida: ${form.pickup}. Entrega: ${form.delivery}. Total estimado: ${money(persistedTicket.total)}. ${form.notes}`;
        setTickets(prev => [persistedTicket, ...prev.filter(item => item.ticket !== persistedTicket.ticket)]);
        setClients(prev => prev.some(client => client.phone === form.phone) ? prev : [...prev, { id: result.clientId || Date.now() + 1, name: form.name, phone: form.phone, email: form.email || "—", address: form.address }]);
        setSent(true);
        setPreviewTicket(persistedTicket);
        window.open(`https://wa.me/573226111910?text=${encodeURIComponent(message)}`, "_blank", "noopener,noreferrer");
      },
      onError: error => toast.error(`No se pudo guardar la solicitud: ${error.message}`),
    });
  };
  return <div className="public-site">
    <header className="public-nav"><a className="public-brand" href="#inicio"><img src="/manus-storage/banner-logo_e91b6326.jpeg" alt="Lavanderia Innovation" /><span>Lavanderia Innovation</span></a><nav><a href="#servicios" onClick={() => setShowServices(true)}>Servicios</a><a href="#pedido">Solicitar domicilio</a><a href="#contacto">Contacto</a></nav><button className="admin-access" onClick={onAdmin}><ShieldCheck size={16} /> Acceder</button></header>
    <main>
      <section className="public-hero" id="inicio"><div className="public-hero-copy"><span className="promo-kicker">LAVANDERÍA Y TINTORERÍA · ZIPAQUIRÁ</span><h1>Tu ropa limpia, <em>sin salir de casa.</em></h1><p>Programa tu domicilio con anticipación. Recogemos, lavamos, secamos y entregamos tus prendas listas.</p><div className="hero-actions"><a className="hero-primary" href="#pedido"><Package size={18} /> Solicitar mi domicilio</a><a className="hero-secondary" href="https://wa.me/573226111910" target="_blank" rel="noreferrer"><Phone size={17} /> 322 611 1910</a></div><div className="hero-trust"><span><Check size={15} /> Domicilio gratis</span><span><Check size={15} /> Confirmación por WhatsApp</span></div></div><div className="hero-art"><img src="/manus-storage/promo-domicilio_4af2fb1f.jpeg" alt="Servicio de domicilio de Lavanderia Innovation" /></div></section>
      <section className="promo-strip"><img src="/manus-storage/promo-cansada_5f1e4aeb.jpeg" alt="Cansada de lavar en casa" /><div><span className="promo-kicker">TU SOLUCIÓN PARA LAVAR EN CASA</span><h2>Lavado, seco y doblado.</h2><p>Déjanos el trabajo pesado. Escríbenos y coordinamos la recogida de tus prendas.</p><a className="hero-primary" href="#pedido">Preguntar ahora <Phone size={16} /></a></div></section>
      {showServices && <section className="public-services" id="servicios"><div className="section-heading"><div><span className="promo-kicker">SERVICIOS PARA TU DÍA A DÍA</span><h2>Todo listo para volver a usar.</h2><p>Elige el servicio que necesitas y cuéntanos qué prendas vamos a recoger.</p></div><button type="button" className="services-close" onClick={() => { setShowServices(false); window.location.hash = "inicio"; }}>× Ocultar servicios</button></div><div className="segment-tabs public-segment-tabs">{["Todos", ...serviceCategories].map(item => <button type="button" key={item} className={selectedCategory === item ? "active" : ""} onClick={() => setSelectedCategory(item as ServiceCategory | "Todos")}>{item}</button>)}</div><div className="public-service-grid">{visibleServices.length ? visibleServices.map(service => <article className="public-service-card" key={service.id}><div className="public-service-icon"><Shirt size={20} /></div><h3>{service.name}</h3><p>{service.description}</p><strong>Desde {money(service.price)}</strong></article>) : <div className="empty-state"><p>En este momento no hay servicios activos para solicitar en línea.</p></div>}</div></section>}
      <section className="order-section" id="pedido"><div className="section-heading"><span className="promo-kicker">SOLICITA TU DOMICILIO</span><h2>Lo recogemos donde estés.</h2><p>Al enviar el formulario se crea el domicilio en nuestro sistema y se abre WhatsApp para confirmar los detalles. Atendemos lunes a viernes de 9:30 a. m. a 12:30 p. m. y de 2:30 p. m. a 5:00 p. m.; sábados de 9:30 a. m. a 12:00 p. m. Los domingos no hay servicio.</p></div><form className="public-order-card" onSubmit={submit}><div className="order-card-heading"><div><h3>Programa tu recogida</h3><p>Te contactaremos para confirmar disponibilidad y horario.</p></div><div className="order-number">01</div></div><div className="order-form-grid"><label>Nombre completo<Input value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} placeholder="Ej. Laura Gómez" /></label><label>Teléfono<Input type="tel" inputMode="numeric" maxLength={10} value={form.phone} onChange={e => setForm({ ...form, phone: sanitizeLocalPhone(e.target.value) })} placeholder="3000000000" /></label><label>Correo electrónico<Input type="email" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} placeholder="cliente@email.com" /></label><label>Servicio<select value={form.service} disabled={!activeServices.length} onChange={e => setForm({ ...form, service: e.target.value })}>{activeServices.length ? activeServices.map(service => <option key={service.id}>{service.name}</option>) : <option value="">No hay servicios disponibles</option>}</select>{(() => { const selected = activeServices.find(service => service.name === form.service); return selected ? <strong className="selected-service-price">Valor del servicio: {money(selected.price)}</strong> : null; })()}</label><label className="field-full">Dirección de recogida<Input value={form.address} onChange={e => setForm({ ...form, address: e.target.value })} placeholder="Dirección, barrio y referencias" /></label><label>Día de recogida<select value={form.day} onChange={e => setForm({ ...form, day: e.target.value })}><option>Lunes</option><option>Martes</option><option>Miércoles</option><option>Jueves</option><option>Viernes</option><option>Sábado</option></select></label><label>Franja de recogida<select value={form.pickup} onChange={e => setForm({ ...form, pickup: e.target.value })}>{form.day === "Sábado" ? <option>9:30 a. m. - 12:00 p. m.</option> : <><option>9:30 a. m. - 12:30 p. m.</option><option>2:30 p. m. - 5:00 p. m.</option></>}</select></label><label>Franja de entrega<select value={form.delivery} onChange={e => setForm({ ...form, delivery: e.target.value })}>{form.day === "Sábado" ? <option>9:30 a. m. - 12:00 p. m.</option> : <><option>2:30 p. m. - 5:00 p. m.</option><option>9:30 a. m. - 12:30 p. m.</option></>}</select></label><label className="field-full">¿Qué prendas vamos a recoger?<Input value={form.clothes} onChange={e => setForm({ ...form, clothes: e.target.value })} placeholder="Ej. 2 bolsas de ropa, 1 edredón" /></label><label className="field-full">Notas adicionales<Input value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} placeholder="Indicaciones para nuestro equipo" /></label></div><div className="order-submit-row"><span><ShieldCheck size={16} /> Tus datos se usan solo para coordinar el domicilio.</span><Button type="submit"><Phone size={17} /> Crear domicilio y confirmar por WhatsApp</Button></div>{sent && <div className="order-success"><Check size={17} /> Solicitud creada. Revisa WhatsApp para confirmar tu pedido.</div>}</form></section>
    </main>
    <Dialog open={previewTicket !== null} onOpenChange={open => !open && setPreviewTicket(null)}><DialogContent className="receipt-dialog public-receipt-dialog"><DialogHeader className="receipt-dialog-header"><div><DialogTitle>Solicitud creada</DialogTitle><DialogDescription>Revisa la tira térmica y decide si deseas imprimirla.</DialogDescription></div><Button onClick={() => window.print()}><Printer size={16} /> Imprimir</Button></DialogHeader>{previewTicket && <div className="receipt-dialog-scroll"><div className="thermal-receipt">{previewTicket.archived && <div className={`receipt-watermark ${previewTicket.status === "Cancelado" ? "cancelled" : "archived"}`}>{previewTicket.status === "Cancelado" ? "CANCELADO" : "ARCHIVADO"}</div>}<div className="receipt-brand">LAVANDERIA<br />INNOVATION</div><div className="receipt-subtitle">LAVANDERÍA Y TINTORERÍA<br />Zipaquirá, Colombia<br />Tel. +57 300 000 0000</div><div className="receipt-line">================================</div><div className="receipt-meta"><span>TICKET: {previewTicket.ticket}</span><span>{new Date().toLocaleDateString("es-CO")}</span><span>{new Date().toLocaleTimeString("es-CO", { hour: "2-digit", minute: "2-digit" })}</span></div><div className="receipt-line">--------------------------------</div><div className="receipt-section"><b>CLIENTE</b><span>{previewTicket.client}</span><span>Tel. {previewTicket.phone}</span><span>{previewTicket.address}</span></div><div className="receipt-line">--------------------------------</div><div className="receipt-section"><b>SERVICIO</b><span>{previewTicket.service}</span><span>{previewTicket.clothes}</span><span>Recogida: {previewTicket.pickup}</span><span>Entrega: {previewTicket.delivery}</span><span>Estado: {previewTicket.status}</span></div><div className="receipt-line">--------------------------------</div><div className="receipt-total"><span>TOTAL</span><strong>{money(previewTicket.total)}</strong></div><div className="receipt-line">================================</div><div className="receipt-thanks">Gracias por confiar en<br />Lavanderia Innovation</div></div></div>}<DialogFooter><Button variant="outline" onClick={() => setPreviewTicket(null)}>Cerrar</Button><Button className="print-full" onClick={() => window.print()}><Printer size={16} /> Imprimir factura</Button></DialogFooter></DialogContent></Dialog>
    <footer className="public-footer" id="contacto"><div><b>Lavanderia Innovation</b><span>Lavandería y tintorería a domicilio en Zipaquirá.</span></div><a href="https://wa.me/573226111910" target="_blank" rel="noreferrer"><Phone size={15} /> 322 611 1910</a><button onClick={onAdmin}><ShieldCheck size={15} /> Acceder</button></footer>
  </div>;
}
